127	    private DirectorioAcademico ExcluirCodigosDePersonas(DirectorioAcademico directorio)
128	    {
129	        var catalogo = _dependencias.Configuracion.Catalogo;
130	        for (var indice = 0; indice < catalogo.Count; indice++)
131	        {
132	            if (CatalogoAsignaturas.EsIdDePersona(catalogo[indice].Codigo, directorio))
133	            {
134	                _dependencias.Configuracion.AdvertirUnaVez($"{Textos.PrefijoConfiguracionIgnorada}: Autorizacion:Asignaturas:{indice}:Codigo = \"{catalogo[indice].Codigo}\" (coincide con el ID de una persona del registro); se excluye del catálogo");
135	            }
136	        }
137	
138	        return directorio with { CodigosAsignatura = [.. directorio.CodigosAsignatura.Where(codigo => !CatalogoAsignaturas.EsIdDePersona(codigo, directorio))] };
139	    }
140	
141	    private async Task<ResultadoPregunta> ResponderSiEsRelevanteAsync(SesionPregunta sesion, CancellationToken cancellationToken)
142	    {
143	        var pregunta = sesion.Entrada.Pregunta;
144	        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
145	        var recuperadas = _dependencias.BaseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(pregunta), _dependencias.Limites.MaximoSeccionesRecuperadas);
146	        sesion.Secciones = SeccionDeDerogacion.Agregar(recuperadas, pregunta, _dependencias.BaseConocimiento);
147	        var activacion = ActivadorResumenPropio.Evaluar(contexto, pregunta, CatalogoAsignaturas.Vigente(_dependencias.Configuracion.Catalogo, sesion.Directorio));
148	        if (_relevancia.PeriodoNoDisponible(contexto, pregunta, activacion))
149	        {
150	            return _emisor.SinInformacion(sesion);
151	        }
152	
153	        sesion.Activacion = await _lectorResumen.VerificarMatriculaAsync(contexto, activacion, sesion.Api, sesion.Registro, cancellationToken);
154	        return _relevancia.DebeResponderSinInformacion(contexto, pregunta, sesion.Secciones, sesion.Activacion)
155	            ? _emisor.SinInformacion(sesion)
156	            : await ResponderConReservaAsync(sesion, cancellationToken);
157	    }
158	
159	    private async Task<ResultadoPregunta> ResponderConReservaAsync(SesionPregunta sesion, CancellationToken cancellationToken)
160	    {
161	        var reserva = _dependencias.Configuracion.ReservaPorPeticionUsd;
162	        if (!_dependencias.Presupuesto.TryReservar(reserva))
163	        {
164	            return _emisor.NoDisponible(sesion, ResultadoAuditoria.Error) with { SegundosParaReintentar = _dependencias.Presupuesto.SegundosHastaElReinicio() };
165	        }
166	
167	        sesion.ReservaHecha = true;
168	        try
169	        {
170	            return await ResponderConTimeoutAsync(sesion, cancellationToken);
171	        }
172	        finally
173	        {
174	            Sustituir(sesion, reserva);
175	        }
176	    }
177	
178	    private void Sustituir(SesionPregunta sesion, decimal reserva)
179	    {
180	        _dependencias.Presupuesto.Sustituir(reserva, _dependencias.Configuracion.GastoDe(sesion.Uso.Valor, 1 + sesion.ReservasExtra));
181	        for (var extra = 0; extra < sesion.ReservasExtra; extra++)
182	        {
183	            _dependencias.Presupuesto.Sustituir(reserva, 0m);
184	        }
185	    }
186	
187	    private async Task<ResultadoPregunta> ResponderConTimeoutAsync(SesionPregunta sesion, CancellationToken cancellationToken)
188	    {
189	        using var temporizador = new CancellationTokenSource(TimeSpan.FromSeconds(_dependencias.Limites.TimeoutLlmSegundos), _tiempo);
190	        using var limite = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, temporizador.Token);
191	        try
192	        {
193	            return await _fase.ResponderAsync(sesion, limite.Token, cancellationToken);
194	        }
195	        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
196	        {
197	            throw new DependenciaNoDisponibleException("El tiempo total de la petición se agotó.");
198	        }
199	    }
200	}
