1	using TutorFlow.Core.Autorizacion;
2	using TutorFlow.Core.Conocimiento;
3	
4	namespace TutorFlow.Core.Asistente;
5	
6	internal sealed record CierreEvaluado(
7	    string Texto,
8	    IReadOnlyList<Cita> Citas,
9	    ResultadoAuditoria Resultado,
10	    bool? UsoDatos,
11	    bool Bloqueado,
12	    string? MotivoDeReintento)
13	{
14	    public static CierreEvaluado Entregable(string texto, IReadOnlyList<Cita> citas, ResultadoAuditoria resultado, bool? usoDatos = null) =>
15	        new(texto, citas, resultado, usoDatos, false, null);
16	}
17	
18	internal sealed class CierreDeRespuesta
19	{
20	    private readonly IBaseConocimiento _baseConocimiento;
21	    private readonly PoliticaAcceso _politicaAcceso;
22	    private readonly VerificadorSalida _verificadorSalida;
23	    private readonly ConfiguracionAsistente _configuracion;
24	    private readonly CitasDeRespuesta _citasDeRespuesta;
25	    private readonly CitasDeReglasAplicadas _citasDeReglas;
26	    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;
27	    private readonly DefinitivaPorAsignatura _definitivaPorAsignatura;
28	    private readonly AfirmacionesDeEstado _afirmacionesDeEstado;
29	
30	    public CierreDeRespuesta(
31	        IBaseConocimiento baseConocimiento,
32	        PoliticaAcceso politicaAcceso,
33	        VerificadorSalida verificadorSalida,
34	        ConfiguracionAsistente configuracion)
35	    {
36	        _baseConocimiento = baseConocimiento;
37	        _politicaAcceso = politicaAcceso;
38	        _verificadorSalida = verificadorSalida;
39	        _configuracion = configuracion;
40	        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
41	        _definitivaPorAsignatura = new DefinitivaPorAsignatura(configuracion.Catalogo);
42	        _citasDeReglas = new CitasDeReglasAplicadas(baseConocimiento, _definitivaPorAsignatura);
43	        _afirmacionesDePerdida = new AfirmacionesDePerdida(configuracion.Catalogo);
44	        _afirmacionesDeEstado = new AfirmacionesDeEstado(configuracion.Catalogo);
45	    }
46	
47	    public CierreEvaluado Evaluar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
48	    {
49	        var propio = IntroduccionDelModelo(sesion, texto);
50	        if (propio.Trim() == Textos.SinInformacion)
51	        {
52	            return SinIntroduccion(sesion, entrada);
53	        }
54	
55	        var escritas = EscritasValidas(sesion, propio, entrada);
56	        var limpio = Limpiar(propio, escritas);
57	        return ReferenciasEscritas.TieneContenido(limpio) || HayFuga(sesion, limpio, entrada)
58	            ? Verificar(sesion, limpio, escritas, entrada)
59	            : SinIntroduccion(sesion, entrada);
60	    }
61	
62	    private static string IntroduccionDelModelo(SesionPregunta sesion, string texto) =>
63	        sesion.Desglose is null ? texto : IntroduccionDelDesglose.SinCifras(texto);
64	
65	    private static string Limpiar(string texto, IReadOnlyList<Cita> escritas) =>
66	        Textos.CitasDeTextoFijo(texto) is null ? ReferenciasEscritas.Limpiar(texto, escritas) : texto;
67	
68	    private CierreEvaluado SinIntroduccion(SesionPregunta sesion, EntradaConversacion entrada) =>
69	        sesion.Desglose is null
70	            ? CierreEvaluado.Entregable(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion)
71	            : Completar(sesion, string.Empty, [], entrada);
72	
73	    private bool HayFuga(SesionPregunta sesion, string limpio, EntradaConversacion entrada) =>
74	        DetectorFugaConfiguracion.HayFuga(limpio, Confidencial(sesion, entrada), sesion.Registro.Fuentes);
75	
76	    private IReadOnlyList<Cita> EscritasValidas(SesionPregunta sesion, string texto, EntradaConversacion entrada)
77	    {
78	        var usadas = _citasDeReglas.Usadas(sesion.Registro, ExtractorCitas.SinCitas(texto), sesion.Directorio);
79	        return _verificadorSalida.DescartarCitasInexistentes(
80	            _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas, usadas),
81	            _baseConocimiento);
82	    }
83	
84	    private CierreEvaluado Verificar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
85	    {
86	        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, sesion.Directorio);
