66	        _relevancia = new RelevanciaPrevia(dependencias.PoliticaAcceso, dependencias.Configuracion.RelevanciaMinima);
67	        _emisor = new EmisorDeResultados(dependencias.Auditor, dependencias.PoliticaAcceso, dependencias.Configuracion);
68	        _fase = FaseDelModelo.Ensamblar(dependencias, _emisor);
