71	    public async Task<ResultadoPregunta> EjecutarAsync(
72	        PreguntaEntrada entrada,
73	        string ipOrigen,
74	        string correlationId,
75	        CancellationToken cancellationToken)
76	    {
77	        var presupuestoApi = TimeSpan.FromSeconds(_dependencias.Limites.PresupuestoApiAcademicaSegundos);
78	        var api = new ApiAcademicaConPresupuesto(_dependencias.ApiAcademica, presupuestoApi, _tiempo);
79	        var sesion = new SesionPregunta(entrada, ipOrigen, correlationId, api, _tiempo);
80	        try
81	        {
82	            return await ResponderSesionAsync(sesion, cancellationToken);
83	        }
84	        catch (Exception)
85	        {
86	            _emisor.Auditar(sesion, ResultadoAuditoria.Error, null, []);
87	            throw;
88	        }
89	    }
