91	    private async Task<ResultadoPregunta> ResponderSesionAsync(SesionPregunta sesion, CancellationToken cancellationToken)
92	    {
93	        var directorio = await ConstructorDirectorio.ConstruirAsync(sesion.Entrada.Usuario, sesion.Api, _dependencias.Configuracion.CodigosAsignatura, cancellationToken);
94	        if (directorio is not null)
95	        {
96	            _dependencias.Auditor.RecordarPersonas(directorio);
97	            sesion.Directorio = ExcluirCodigosDePersonas(directorio);
98	        }
99	
100	        var identidad = _dependencias.PoliticaAcceso.EvaluarIdentidad(sesion.Entrada.Usuario, sesion.Directorio);
101	        if (!identidad.Permitido)
102	        {
103	            return _emisor.Denegar(sesion, identidad.Motivo, 0);
104	        }
105	
106	        AuditarIdentidades(sesion);
107	        return await ResponderSiEstaAutorizadoAsync(sesion, cancellationToken);
108	    }
