110	    private async Task<ResultadoPregunta> ResponderSiEstaAutorizadoAsync(SesionPregunta sesion, CancellationToken cancellationToken)
111	    {
112	        var decision = _dependencias.PoliticaAcceso.EvaluarPregunta(sesion.Entrada.Usuario, sesion.Entrada.Pregunta, sesion.Directorio);
113	        return decision.Permitido
114	            ? await ResponderSiEsRelevanteAsync(sesion, cancellationToken)
115	            : _emisor.Denegar(sesion, decision.Motivo, 0);
116	    }
