118	    private void AuditarIdentidades(SesionPregunta sesion)
119	    {
120	        var identidades = _limitadorIdentidades?.Registrar(sesion.IpOrigen, sesion.Entrada.Usuario.Id);
121	        if (identidades is { SuperacionNueva: true })
122	        {
123	            _dependencias.Auditor.RegistrarMultiplesIdentidades(sesion.IpOrigen, identidades.Ids);
124	        }
125	    }
