18	internal sealed class CierreDeRespuesta
19	{
20	    private readonly IBaseConocimiento _baseConocimiento;
21	    private readonly PoliticaAcceso _politicaAcceso;
22	    private readonly VerificadorSalida _verificadorSalida;
23	    private readonly ConfiguracionAsistente _configuracion;
24	    private readonly CitasDeRespuesta _citasDeRespuesta;
25	    private readonly CitasDeReglasAplicadas _citasDeReglas;
26	    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;
27	    private readonly DefinitivaPorAsignatura _definitivaPorAsignatura;
28	    private readonly AfirmacionesDeEstado _afirmacionesDeEstado;
29	
30	    public CierreDeRespuesta(
31	        IBaseConocimiento baseConocimiento,
32	        PoliticaAcceso politicaAcceso,
33	        VerificadorSalida verificadorSalida,
34	        ConfiguracionAsistente configuracion)
35	    {
36	        _baseConocimiento = baseConocimiento;
37	        _politicaAcceso = politicaAcceso;
38	        _verificadorSalida = verificadorSalida;
39	        _configuracion = configuracion;
40	        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
41	        _definitivaPorAsignatura = new DefinitivaPorAsignatura(configuracion.Catalogo);
42	        _citasDeReglas = new CitasDeReglasAplicadas(baseConocimiento, _definitivaPorAsignatura);
43	        _afirmacionesDePerdida = new AfirmacionesDePerdida(configuracion.Catalogo);
44	        _afirmacionesDeEstado = new AfirmacionesDeEstado(configuracion.Catalogo);
45	    }
46	
47	    public CierreEvaluado Evaluar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
48	    {
49	        var propio = IntroduccionDelModelo(sesion, texto);
50	        if (propio.Trim() == Textos.SinInformacion)
51	        {
52	            return SinIntroduccion(sesion, entrada);
53	        }
54	
55	        var escritas = EscritasValidas(sesion, propio, entrada);
56	        var limpio = Limpiar(propio, escritas);
57	        return ReferenciasEscritas.TieneContenido(limpio) || HayFuga(sesion, limpio, entrada)
58	            ? Verificar(sesion, limpio, escritas, entrada)
59	            : SinIntroduccion(sesion, entrada);
60	    }
61	
62	    private static string IntroduccionDelModelo(SesionPregunta sesion, string texto) =>
63	        sesion.Desglose is null ? texto : IntroduccionDelDesglose.SinCifras(texto);
64	
65	    private static string Limpiar(string texto, IReadOnlyList<Cita> escritas) =>
66	        Textos.CitasDeTextoFijo(texto) is null ? ReferenciasEscritas.Limpiar(texto, escritas) : texto;
67	
68	    private CierreEvaluado SinIntroduccion(SesionPregunta sesion, EntradaConversacion entrada) =>
69	        sesion.Desglose is null
70	            ? CierreEvaluado.Entregable(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion)
71	            : Completar(sesion, string.Empty, [], entrada);
72	
73	    private bool HayFuga(SesionPregunta sesion, string limpio, EntradaConversacion entrada) =>
74	        DetectorFugaConfiguracion.HayFuga(limpio, Confidencial(sesion, entrada), sesion.Registro.Fuentes);
75	
76	    private IReadOnlyList<Cita> EscritasValidas(SesionPregunta sesion, string texto, EntradaConversacion entrada)
77	    {
78	        var usadas = _citasDeReglas.Usadas(sesion.Registro, ExtractorCitas.SinCitas(texto), sesion.Directorio);
79	        return _verificadorSalida.DescartarCitasInexistentes(
80	            _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas, usadas),
81	            _baseConocimiento);
82	    }
83	
84	    private CierreEvaluado Verificar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
85	    {
86	        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, sesion.Directorio);
87	        var verificada = VerificarSalida(sesion, limpio, escritas, autorizados, entrada);
88	        if (verificada.Resultado != ResultadoAuditoria.Respondida)
89	        {
90	            return new CierreEvaluado(verificada.Respuesta, verificada.Citas, verificada.Resultado, null, true, verificada.MotivoDeReintento);
91	        }
92	
93	        var motivo = MotivoDeAfirmacionNoVerificable(sesion, limpio, autorizados);
94	        return motivo is null
95	            ? Completar(sesion, limpio, escritas, entrada)
96	            : new CierreEvaluado(Textos.NoVerificable, [], ResultadoAuditoria.EstadoNoVerificado, null, true, motivo);
97	    }
98	
99	    private SalidaVerificada VerificarSalida(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, IReadOnlyCollection<string> autorizados, EntradaConversacion entrada) =>
100	        _verificadorSalida.Verificar(
101	            sesion.Entrada.Usuario,
102	            limpio,
103	            escritas,
104	            autorizados,
105	            sesion.Registro.Fuentes,
106	            _baseConocimiento,
107	            sesion.Directorio,
108	            Confidencial(sesion, entrada));
109	
110	    private string? MotivoDeAfirmacionNoVerificable(SesionPregunta sesion, string respuesta, IReadOnlyCollection<string> autorizados)
111	    {
112	        var usuario = sesion.Entrada.Usuario;
113	        var bloques = BloquesDeRespuesta.De(respuesta);
114	        var resumenes = sesion.Registro.Resumenes;
115	        var contexto = new ContextoDeAfirmaciones(usuario, autorizados, sesion.Directorio, resumenes);
116	        return _afirmacionesDePerdida.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes)
117	            ?? _afirmacionesDeEstado.Motivo(bloques, contexto)
118	            ?? _definitivaPorAsignatura.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes)
119	            ?? CamposLigados.Motivo(bloques, contexto);
120	    }
121	
122	    private CierreEvaluado Completar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
123	    {
124	        var citasDeTextoFijo = Textos.CitasDeTextoFijo(limpio);
125	        if (citasDeTextoFijo is not null)
126	        {
127	            return CierreEvaluado.Entregable(limpio, citasDeTextoFijo, ResultadoAuditoria.Respondida);
128	        }
129	
130	        var completo = ConDesglose(sesion, limpio);
131	        var documentos = CitasDeDocumento(sesion, completo, escritas, entrada);
132	        if (documentos.Count == 0 && !sesion.Registro.UsoDatos)
133	        {
134	            return new CierreEvaluado(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, false, true, null);
135	        }
136	
137	        IReadOnlyList<Cita> citas = [.. documentos.Concat(sesion.Registro.Citas).Distinct()];
138	        return CierreEvaluado.Entregable(completo, citas, ResultadoAuditoria.Respondida);
139	    }
140	
141	    private static string ConDesglose(SesionPregunta sesion, string introduccion)
142	    {
143	        if (sesion.Desglose is not { } desglose)
144	        {
145	            return introduccion;
146	        }
147	
148	        return introduccion.Length == 0 ? desglose : $"{introduccion}\n\n{desglose}";
149	    }
150	
151	    private IReadOnlyList<Cita> CitasDeDocumento(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
152	    {
153	        var usadas = _citasDeReglas.Usadas(sesion.Registro, limpio, sesion.Directorio);
154	        var vigentes = escritas.Where(cita => !sesion.Registro.Reglas.Contains(cita) || usadas.Contains(cita)).ToList();
155	        var reglas = _citasDeReglas.De(usadas, sesion.Entrada.Pregunta, vigentes);
156	        IReadOnlyList<Cita> sinRespaldo = [.. vigentes.Concat(reglas).Concat(_citasDeRespuesta.PorTema(limpio, entrada.Secciones)).Distinct()];
157	        return sinRespaldo.Count > 0 || sesion.Registro.UsoDatos ? sinRespaldo : _citasDeRespuesta.Respaldo(limpio, entrada.Secciones);
158	    }
159	
160	    private MaterialConfidencial Confidencial(SesionPregunta sesion, EntradaConversacion entrada) =>
161	        new(
162	            _configuracion.MarcadorCanario,
163	            [ConstructorPrompts.Instrucciones(entrada.PromptSistema), .. DescripcionesDeHerramientas(sesion.Entrada.Usuario.Rol)],
164	            HerramientasAsistente.NombresInternos);
165	
166	    private static IEnumerable<string> DescripcionesDeHerramientas(Rol rol) =>
167	        HerramientasAsistente.Definir(rol)
168	            .SelectMany(herramienta => herramienta.Parametros.Select(parametro => parametro.Descripcion).Prepend(herramienta.Descripcion));
169	}
