3	namespace TutorFlow.Core.Asistente;
4	
5	internal sealed class FaseDelModelo
6	{
7	    private const string InicioDeLaInstruccion = "Tu respuesta anterior no se pudo verificar: ";
8	    private const string FinDeLaInstruccion = ". Responde de nuevo usando solo los datos y las secciones entregados.";
9	
10	    private readonly IClienteLlm _clienteLlm;
11	    private readonly PoliticaAcceso _politicaAcceso;
12	    private readonly LimitesAsistente _limites;
13	    private readonly ConfiguracionAsistente _configuracion;
14	    private readonly PresupuestoDiario _presupuesto;
15	    private readonly EmisorDeResultados _emisor;
16	    private readonly CierreDeRespuesta _cierre;
17	    private readonly LectorResumenPropio _lectorResumen;
18	    private readonly DesgloseDeFaltas _desglose;
19	
20	    public static FaseDelModelo Ensamblar(DependenciasDeAsistente d, EmisorDeResultados emisor)
21	    {
22	        var cierre = new CierreDeRespuesta(d.BaseConocimiento, d.PoliticaAcceso, d.VerificadorSalida, d.Configuracion);
23	        return new FaseDelModelo(d.ClienteLlm, d.PoliticaAcceso, d.Limites, d.Configuracion, d.Presupuesto, emisor, cierre);
24	    }
25	
26	    public FaseDelModelo(
27	        IClienteLlm clienteLlm,
28	        PoliticaAcceso politicaAcceso,
29	        LimitesAsistente limites,
30	        ConfiguracionAsistente configuracion,
31	        PresupuestoDiario presupuesto,
32	        EmisorDeResultados emisor,
33	        CierreDeRespuesta cierre)
34	    {
35	        _clienteLlm = clienteLlm;
36	        _politicaAcceso = politicaAcceso;
37	        _limites = limites;
38	        _configuracion = configuracion;
39	        _presupuesto = presupuesto;
40	        _emisor = emisor;
41	        _cierre = cierre;
42	        _lectorResumen = new LectorResumenPropio(politicaAcceso);
43	        _desglose = new DesgloseDeFaltas(politicaAcceso, configuracion.Catalogo);
44	    }
45	
46	    public async Task<ResultadoPregunta> ResponderAsync(SesionPregunta sesion, CancellationToken limite, CancellationToken cliente)
47	    {
48	        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
49	        var herramientas = new HerramientasAsistente(sesion.Api, _politicaAcceso);
50	        var entrada = await PrepararEntradaAsync(sesion, contexto, herramientas, limite);
51	        var conversacion = new ConversacionLlm(_clienteLlm, herramientas, _limites, sesion.Uso, _configuracion);
52	        var resultado = await conversacion.EjecutarAsync(contexto, entrada, sesion.Registro, limite);
53	        return resultado.Estado == EstadoConversacion.Completada
54	            ? await CerrarAsync(new Turno(sesion, contexto, entrada, conversacion, resultado), limite, cliente)
55	            : Terminal(sesion, resultado);
56	    }
57	
58	    private async Task<ResultadoPregunta> CerrarAsync(Turno turno, CancellationToken limite, CancellationToken cliente)
59	    {
60	        var primero = _cierre.Evaluar(turno.Sesion, turno.Resultado.Texto ?? string.Empty, turno.Entrada);
61	        if (primero.MotivoDeReintento is null || !_presupuesto.TryReservar(_configuracion.ReservaPorPeticionUsd))
62	        {
63	            return Emitir(turno.Sesion, primero);
64	        }
65	
66	        turno.Sesion.ReservasExtra++;
67	        turno.Sesion.Reintento = true;
68	        try
69	        {
70	            return await ReintentarAsync(turno, primero, limite);
71	        }
72	        catch (OperationCanceledException) when (!cliente.IsCancellationRequested)
73	        {
74	            return Emitir(turno.Sesion, primero);
75	        }
76	    }
77	
78	    private async Task<ResultadoPregunta> ReintentarAsync(Turno turno, CierreEvaluado primero, CancellationToken limite)
79	    {
80	        var instruccion = $"{InicioDeLaInstruccion}{primero.MotivoDeReintento}{FinDeLaInstruccion}";
81	        var segundo = await turno.Conversacion.ReintentarAsync(turno.Contexto, turno.Entrada.PromptSistema, turno.Resultado, instruccion, turno.Sesion.Registro, limite);
82	        return segundo.Estado switch
83	        {
84	            EstadoConversacion.Completada => Emitir(turno.Sesion, ElegirEntre(primero, _cierre.Evaluar(turno.Sesion, segundo.Texto ?? string.Empty, turno.Entrada))),
85	            EstadoConversacion.IdAjeno => _emisor.Denegar(turno.Sesion, MotivoDenegacion.HerramientaIdAjeno, turno.Sesion.Uso.Valor.Total, segundo.IdSolicitado),
86	            _ => Emitir(turno.Sesion, primero)
87	        };
88	    }
89	
90	    private static CierreEvaluado ElegirEntre(CierreEvaluado primero, CierreEvaluado segundo) => segundo.Bloqueado ? primero : segundo;
91	
92	    private ResultadoPregunta Emitir(SesionPregunta sesion, CierreEvaluado cierre) =>
93	        _emisor.Responder(sesion, cierre.Texto, cierre.Citas, cierre.Resultado, cierre.UsoDatos);
94	
95	    private ResultadoPregunta Terminal(SesionPregunta sesion, ResultadoConversacion resultado) => resultado.Estado switch
96	    {
97	        EstadoConversacion.IdAjeno => _emisor.Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, sesion.Uso.Valor.Total, resultado.IdSolicitado),
98	        EstadoConversacion.LimiteHerramientas => _emisor.NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
99	        EstadoConversacion.ContextoTruncado => ResponderContextoTruncado(sesion),
100	        _ => _emisor.Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error)
101	    };
102	
103	    private ResultadoPregunta ResponderContextoTruncado(SesionPregunta sesion)
104	    {
105	        sesion.ContextoTruncado = true;
106	        return _emisor.Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error);
107	    }
108	
109	    private async Task<EntradaConversacion> PrepararEntradaAsync(SesionPregunta sesion, ContextoUsuario contexto, HerramientasAsistente herramientas, CancellationToken cancellationToken)
110	    {
111	        var resumen = await _lectorResumen.LeerAsync(contexto, sesion.Activacion, sesion.Api, sesion.Registro, cancellationToken);
112	        sesion.Desglose = await _desglose.PrepararAsync(sesion, contexto, cancellationToken);
113	        var prelectura = sesion.Desglose is null ? await PrelecturaAsync(sesion, contexto, herramientas, cancellationToken) : null;
114	        foreach (var seccion in sesion.Secciones)
115	        {
116	            sesion.Registro.AgregarFuente(ConstructorPrompts.ContenidoEntregado(seccion));
117	        }
118	
119	        var prompt = ConstructorPrompts.PromptSistema(contexto.Usuario.Rol, _configuracion.MarcadorCanario);
120	        return new EntradaConversacion(sesion.Entrada.Pregunta, sesion.Secciones, resumen, prelectura, prompt, sesion.Desglose is not null);
121	    }
122	
123	    private async Task<string?> PrelecturaAsync(SesionPregunta sesion, ContextoUsuario contexto, HerramientasAsistente herramientas, CancellationToken cancellationToken)
124	    {
125	        var programas = _politicaAcceso.ProgramasAutorizados(contexto.Usuario, contexto.Directorio);
126	        var palabras = TokenizadorTexto.Valores(sesion.Entrada.Pregunta);
127	        return ActivadorPrelectura.Activa(contexto, palabras, programas)
128	            ? await herramientas.LeerProgramaAsync(contexto, sesion.Registro, cancellationToken)
129	            : null;
130	    }
131	
132	    private sealed record Turno(SesionPregunta Sesion, ContextoUsuario Contexto, EntradaConversacion Entrada, ConversacionLlm Conversacion, ResultadoConversacion Resultado);
133	}
