4	namespace TutorFlow.Core.Asistente;
5	
6	public enum EstadoConversacion
7	{
8	    Completada,
9	    Rechazada,
10	    LimiteHerramientas,
11	    IdAjeno,
12	    ContextoTruncado
13	}
14	
15	public sealed record ResultadoConversacion(
16	    EstadoConversacion Estado,
17	    string? Texto,
18	    string? IdSolicitado = null,
19	    IReadOnlyList<MensajeLlm>? Mensajes = null,
20	    int Invocaciones = 0);
21	
22	internal sealed record EntradaConversacion(
23	    string Pregunta,
24	    IReadOnlyList<SeccionDocumento> Secciones,
25	    ResumenEntregado? Resumen,
26	    string? Prelectura,
27	    string PromptSistema,
28	    bool ConDesglose = false);
29	
30	internal sealed class ConversacionLlm
31	{
32	    private readonly IClienteLlm _clienteLlm;
33	    private readonly HerramientasAsistente _herramientas;
34	    private readonly LimitesAsistente _limites;
35	    private readonly UsoAcumulado _uso;
36	    private readonly ConfiguracionAsistente _configuracion;
37	
38	    public ConversacionLlm(
39	        IClienteLlm clienteLlm,
40	        HerramientasAsistente herramientas,
41	        LimitesAsistente limites,
42	        UsoAcumulado uso,
43	        ConfiguracionAsistente configuracion)
44	    {
45	        _clienteLlm = clienteLlm;
46	        _herramientas = herramientas;
47	        _limites = limites;
48	        _uso = uso;
49	        _configuracion = configuracion;
50	    }
51	
52	    public async Task<ResultadoConversacion> EjecutarAsync(
53	        ContextoUsuario contexto,
54	        EntradaConversacion entrada,
55	        RegistroConsultas registro,
56	        CancellationToken cancellationToken)
57	    {
58	        var estado = new Turnos(
59	            contexto,
60	            registro,
61	            [ConstructorPrompts.MensajeInicial(entrada.Pregunta, entrada.Secciones, entrada.Resumen, entrada.Prelectura, entrada.ConDesglose)],
62	            entrada.PromptSistema);
63	        return await CorrerAsync(estado, cancellationToken);
64	    }
65	
66	    public async Task<ResultadoConversacion> ReintentarAsync(
67	        ContextoUsuario contexto,
68	        string promptSistema,
69	        ResultadoConversacion anterior,
70	        string instruccion,
71	        RegistroConsultas registro,
72	        CancellationToken cancellationToken)
73	    {
74	        List<MensajeLlm> mensajes =
75	        [
76	            .. anterior.Mensajes ?? [],
77	            new MensajeLlm(RolMensaje.Asistente, anterior.Texto ?? string.Empty, null, []),
78	            new MensajeLlm(RolMensaje.Usuario, instruccion, null, [])
79	        ];
80	        return await CorrerAsync(new Turnos(contexto, registro, mensajes, promptSistema) { Invocaciones = anterior.Invocaciones }, cancellationToken);
81	    }
82	
83	    private async Task<ResultadoConversacion> CorrerAsync(Turnos estado, CancellationToken cancellationToken)
84	    {
85	        ResultadoConversacion? final = null;
86	        while (final is null)
87	        {
88	            final = await AvanzarAsync(estado, cancellationToken);
89	        }
90	
91	        return final;
92	    }
93	
94	    private async Task<ResultadoConversacion?> AvanzarAsync(Turnos estado, CancellationToken cancellationToken)
95	    {
96	        var respuesta = await _clienteLlm.CompletarAsync(Solicitar(estado), cancellationToken);
97	        _uso.Sumar(respuesta.Uso);
98	        estado.Invocaciones += respuesta.Llamadas.Count;
99	        var terminal = Terminal(estado, respuesta);
100	        return terminal ?? await EjecutarHerramientasAsync(estado, respuesta, cancellationToken);
101	    }
102	
103	    private ResultadoConversacion? Terminal(Turnos estado, RespuestaLlm respuesta)
104	    {
105	        if (respuesta.ContextoTruncado is { } truncado)
106	        {
107	            return ContextoTruncado(truncado);
108	        }
109	
110	        if (respuesta.Rechazada)
111	        {
112	            return new ResultadoConversacion(EstadoConversacion.Rechazada, null);
113	        }
114	
115	        return respuesta.Llamadas.Count == 0 ? Completada(estado, respuesta) : LimiteSuperado(estado);
116	    }
