118	    private static ResultadoConversacion Completada(Turnos estado, RespuestaLlm respuesta) =>
119	        new(EstadoConversacion.Completada, respuesta.Texto, null, [.. estado.Mensajes], estado.Invocaciones);
120	
121	    private ResultadoConversacion? LimiteSuperado(Turnos estado) =>
122	        estado.Invocaciones > _limites.MaximoInvocacionesHerramientas
123	            ? new ResultadoConversacion(EstadoConversacion.LimiteHerramientas, null)
124	            : null;
