126	    private ResultadoConversacion ContextoTruncado(ContextoTruncadoDetectado truncado)
127	    {
128	        _configuracion.Advertir($"Contexto del proveedor local truncado: estimación de {truncado.TokensEstimados} tokens y prompt_tokens reportados {truncado.TokensReportados}.");
129	        return new ResultadoConversacion(EstadoConversacion.ContextoTruncado, null);
130	    }
