132	    private async Task<ResultadoConversacion?> EjecutarHerramientasAsync(Turnos estado, RespuestaLlm respuesta, CancellationToken cancellationToken)
133	    {
134	        estado.Mensajes.Add(new MensajeLlm(RolMensaje.Asistente, respuesta.Texto ?? string.Empty, null, SoloLasEjecutables(respuesta.Llamadas, estado.Contexto.Usuario.Rol)));
135	        foreach (var llamada in respuesta.Llamadas)
136	        {
137	            var resultado = await _herramientas.EjecutarAsync(llamada, estado.Contexto, estado.Registro, cancellationToken);
138	            if (resultado.IdAjeno)
139	            {
140	                return new ResultadoConversacion(EstadoConversacion.IdAjeno, null, resultado.IdSolicitado);
141	            }
142	
143	            estado.Registro.AgregarFuente(resultado.Contenido);
144	            estado.Mensajes.Add(new MensajeLlm(RolMensaje.Herramienta, resultado.Contenido, llamada.Id, []));
145	        }
146	
147	        return null;
148	    }
