10	    public static string? De(ResumenEstudiante resumen, IReadOnlyCollection<string> claves, bool terceraPersona)
11	    {
12	        var elegidas = resumen.Asignaturas
13	            .Where(resultado => claves.Count == 0 || claves.Contains(AmbitoPersonal.Clave(resultado.Asignatura.Codigo)))
14	            .ToList();
15	        return elegidas.Count == 0
16	            ? null
17	            : string.Join("\n", elegidas.Select(resultado => FormateadorDatos.LineaDeAsistencia(resultado, terceraPersona)).Append(Total(elegidas)));
