19	
20	    private static string Total(IReadOnlyList<ResultadoAsignatura> elegidas)
21	    {
22	        var conRegistro = elegidas.Where(resultado => resultado.Asignatura.Asistencia.Inasistencias is not null).ToList();
23	        var sinRegistro = elegidas.Except(conRegistro).Select(resultado => resultado.Asignatura.Nombre).ToList();
24	        var faltas = conRegistro.Sum(resultado => resultado.Asignatura.Asistencia.Inasistencias.GetValueOrDefault());
25	        return conRegistro.Count == 0 ? TotalSinRegistro : $"Total: {faltas} faltas{Complemento(sinRegistro)}";
26	    }
27	
28	    private static string Complemento(List<string> sinRegistro) =>
29	        sinRegistro.Count == 0 ? string.Empty : $" (sin registro: {string.Join(", ", sinRegistro)})";
30	}
