48	    private static string? LineaDeEstado(ResultadoAsignatura resultado)
49	    {
50	        var nombre = resultado.Asignatura.Nombre;
51	        return resultado.Estado switch
52	        {
53	            EstadoAsignatura.Perdida => $"Perdida por nota: {nombre} (definitiva {FormateadorDatos.Nota(resultado.Definitiva)})",
54	            EstadoAsignatura.PerdidaPorInasistencia => $"Perdida por inasistencia: {nombre} (definitiva {FormateadorDatos.Nota(0m)})",
