using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal static class ActivadorPrelectura
{
    private const string PruebaAcademica = " prueba academica ";

    private static readonly HashSet<string> Palabras = new(StringComparer.Ordinal)
    {
        "estudiante", "estudiantes", "programa", "programas", "perdida", "perdidas", "perdido", "perdidos", "perdio", "perdieron",
        "reprobo", "reprobaron", "reprobada", "reprobadas"
    };

    private static readonly string[] FrasesNormativas =
    [
        " que dice ", " segun el reglamento ", " que significa ", " que pasa si ", " un estudiante ", " el estudiante ",
        " cada estudiante ", " una asignatura ", " una materia "
    ];

    private static readonly HashSet<string> Posesivos = new(StringComparer.Ordinal)
    {
        "mi", "mis", "nuestro", "nuestros", "nuestra", "nuestras"
    };

    public static bool Activa(ContextoUsuario contexto, IReadOnlyList<string> palabras, IReadOnlyList<string> programas) =>
        contexto.Usuario.Rol == Rol.Coordinador
        && programas.Count > 0
        && (MencionaEstudianteDeSusProgramas(contexto, palabras, programas) || ActivaPorPalabras(palabras));

    public static bool MencionaEstudianteDeSusProgramas(ContextoUsuario contexto, IReadOnlyList<string> palabras, IReadOnlyList<string> programas) =>
        EstudiantesMencionadosDeSusProgramas(contexto, palabras, programas).Count > 0;

    public static IReadOnlyList<string> EstudiantesMencionadosDeSusProgramas(ContextoUsuario contexto, IReadOnlyList<string> palabras, IReadOnlyList<string> programas)
    {
        var propios = contexto.Directorio.Estudiantes.Where(estudiante => programas.Contains(estudiante.ProgramaId)).Select(estudiante => estudiante.Id).ToHashSet();
        return [.. DetectorTerceros.PersonasMencionadas(string.Join(' ', palabras), contexto.Directorio).Where(propios.Contains).Distinct()];
    }

    private static bool ActivaPorPalabras(IReadOnlyList<string> palabras)
    {
        var texto = $" {string.Join(' ', palabras)} ";
        var hayActivador = palabras.Any(Palabras.Contains) || texto.Contains(PruebaAcademica, StringComparison.Ordinal);
        return hayActivador && (!EsNormativaGenerica(texto) || palabras.Any(Posesivos.Contains));
    }

    private static bool EsNormativaGenerica(string texto) =>
        FrasesNormativas.Any(frase => texto.Contains(frase, StringComparison.Ordinal));
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal static class ActivadorResumenPropio
{
    private const string PalabraPuedo = "puedo";
    private const string PruebaAcademica = " prueba academica ";

    private static readonly string[] GenericosIndefinidos =
    [
        " una materia ", " una asignatura ", " una nota ", " un estudiante "
    ];

    private static readonly HashSet<string> MarcadoresDePrimeraPersona = new(StringComparer.Ordinal)
    {
        "mi", "mis", "tengo", "llevo", "voy", "cumplo", "soy", "estoy", "perdi", "gane", "saque", "quede"
    };

    private static readonly HashSet<string> TerminosGenericos = new(StringComparer.Ordinal)
    {
        "materia", "materias", "asignatura", "asignaturas"
    };

    private static readonly HashSet<string> TerminosDeDatosAcademicos =
    [
        "nota", "notas", "definitiva", "promedio", "corte", "falta", "faltas", "asistencia", .. FormasDePerdida.Inasistencias,
        "beca", "habilitar", "materia", "materias", "asignatura", "asignaturas", "perdida",
        "perdidas", "aprobe"
    ];

    public static ActivacionResumen Evaluar(ContextoUsuario contexto, string pregunta, IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        if (contexto.Usuario.Rol != Rol.Estudiante)
        {
            return ActivacionResumen.Ninguna;
        }

        var palabras = TokenizadorTexto.Valores(pregunta);
        if (PrimeraPersona(contexto, palabras) || PuedoConTerminoEspecifico(palabras))
        {
            return new ActivacionResumen(true, []);
        }

        return new ActivacionResumen(false, CatalogoAsignaturas.CodigosNombrados(pregunta, catalogo, contexto.Directorio.CodigosAsignatura));
    }

    internal static bool PideDatosAcademicos(IReadOnlyList<string> palabras) =>
        palabras.Any(TerminosDeDatosAcademicos.Contains) || Contiene(palabras, PruebaAcademica);

    private static bool PrimeraPersona(ContextoUsuario contexto, IReadOnlyList<string> palabras) =>
        PideDatosAcademicos(palabras)
        && (palabras.Any(MarcadoresDePrimeraPersona.Contains) || MencionaSuNombre(contexto, palabras));

    private static bool PuedoConTerminoEspecifico(IReadOnlyList<string> palabras) =>
        palabras.Contains(PalabraPuedo)
        && TieneTerminoEspecifico(palabras)
        && !GenericosIndefinidos.Any(frase => Contiene(palabras, frase));

    private static bool TieneTerminoEspecifico(IReadOnlyList<string> palabras) =>
        palabras.Any(palabra => TerminosDeDatosAcademicos.Contains(palabra) && !TerminosGenericos.Contains(palabra))
        || Contiene(palabras, PruebaAcademica);

    private static bool Contiene(IReadOnlyList<string> palabras, string frase) =>
        $" {string.Join(' ', palabras)} ".Contains(frase, StringComparison.Ordinal);

    private static bool MencionaSuNombre(ContextoUsuario contexto, IReadOnlyList<string> palabras) =>
        DetectorTerceros.MencionaNombreCompleto(contexto.Usuario.Id, string.Join(' ', palabras), contexto.Directorio);
}
using TutorFlow.Core.Academico;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class LectorResumenPropio
{
    private readonly PoliticaAcceso _politicaAcceso;

    public LectorResumenPropio(PoliticaAcceso politicaAcceso)
    {
        _politicaAcceso = politicaAcceso;
    }

    public async Task<ActivacionResumen> VerificarMatriculaAsync(
        ContextoUsuario contexto,
        ActivacionResumen activacion,
        IApiAcademica api,
        RegistroConsultas registro,
        CancellationToken cancellationToken)
    {
        if (!activacion.RequiereVerificacion || !PuedeLeerSusDatos(contexto))
        {
            return activacion;
        }

        var notas = await api.ObtenerNotasAsync(contexto.Usuario.Id, cancellationToken);
        RegistrarVerificacion(contexto, notas, registro);
        var matriculada = notas.Any(nota => activacion.CodigosNombrados.Contains(AmbitoPersonal.Clave(nota.Codigo)));
        return activacion with { NotasVerificadas = notas, Matriculada = matriculada };
    }

    public async Task<ResumenEntregado?> LeerAsync(
        ContextoUsuario contexto,
        ActivacionResumen activacion,
        IApiAcademica api,
        RegistroConsultas registro,
        CancellationToken cancellationToken)
    {
        if (!activacion.Entrega || !PuedeLeerSusDatos(contexto))
        {
            return null;
        }

        var resumen = await ResumirAsync(contexto, activacion, api, cancellationToken);
        Registrar(contexto, resumen, registro);
        var entregado = FormateadorResumen.Resumir(resumen);
        registro.RegistrarReglas(entregado.EntradasDeReglas);
        registro.AgregarFuente(entregado.Texto);
        return entregado;
    }

    private static Task<ResumenEstudiante> ResumirAsync(
        ContextoUsuario contexto,
        ActivacionResumen activacion,
        IApiAcademica api,
        CancellationToken cancellationToken) =>
        activacion.NotasVerificadas is null
            ? ResumenesAcademicos.ResumirAsync(api, contexto.Usuario.Id, cancellationToken)
            : ResumenesAcademicos.ResumirAsync(api, contexto.Usuario.Id, activacion.NotasVerificadas, cancellationToken);

    private bool PuedeLeerSusDatos(ContextoUsuario contexto) =>
        _politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, contexto.Usuario.Id, contexto.Directorio).Permitido;

    private static string ProgramaDe(ContextoUsuario contexto) =>
        contexto.Directorio.Estudiantes.First(e => e.Id == contexto.Usuario.Id).ProgramaId;

    private static void RegistrarVerificacion(ContextoUsuario contexto, IReadOnlyList<NotasAsignatura> notas, RegistroConsultas registro)
    {
        var datos = DatosLeidos.PorCodigos(contexto.Usuario.Id, ProgramaDe(contexto), notas.Select(n => n.Codigo), RecursoConsultado.Notas);
        registro.RegistrarVerificacion(contexto.Usuario.Id, [RecursoConsultado.Notas], datos);
    }

    private static void Registrar(ContextoUsuario contexto, ResumenEstudiante resumen, RegistroConsultas registro)
    {
        var id = contexto.Usuario.Id;
        registro.Registrar(id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionNotas));
        registro.RegistrarCita(new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionAsistencia));
        registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(contexto), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
        registro.RegistrarResumen(resumen);
    }
}
using TutorFlow.Core.Academico;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public sealed class RegistroConsultas
{
    private readonly List<string> _estudiantes = [];
    private readonly List<RecursoConsultado> _recursos = [];
    private readonly List<DatoConsultado> _datos = [];
    private readonly List<Cita> _citas = [];
    private readonly SortedSet<int> _entradasDeReglas = [];
    private readonly List<string> _fuentes = [];
    private bool _usoDatos;
    private readonly Dictionary<string, ResumenEstudiante> _resumenes = [];

    public IReadOnlyList<string> Estudiantes => _estudiantes;

    public IReadOnlyList<RecursoConsultado> Recursos => _recursos;

    public IReadOnlyList<DatoConsultado> DatosConsultados => _datos;

    public IReadOnlyList<Cita> Citas => _citas;


    public IReadOnlyList<Cita> Reglas => ReglasAplicadas.Citas(_entradasDeReglas);

    public bool ReglasIncluyenNotas => _entradasDeReglas.Contains(0);

    public IReadOnlyDictionary<string, ResumenEstudiante> Resumenes => _resumenes;

    public IReadOnlyList<string> Fuentes => _fuentes;

    public bool UsoDatos => _usoDatos;

    public void Registrar(string estudianteId, IEnumerable<RecursoConsultado> recursos, Cita? cita)
    {
        _usoDatos = true;
        AgregarSiFalta(_estudiantes, estudianteId);
        foreach (var recurso in recursos)
        {
            AgregarSiFalta(_recursos, recurso);
        }

        if (cita is not null)
        {
            AgregarSiFalta(_citas, cita);
        }
    }

    public void RegistrarVerificacion(string estudianteId, IEnumerable<RecursoConsultado> recursos, IEnumerable<DatoConsultado> datos)
    {
        AgregarSiFalta(_estudiantes, estudianteId);
        foreach (var recurso in recursos)
        {
            AgregarSiFalta(_recursos, recurso);
        }

        RegistrarDatos(datos);
    }

    public void RegistrarDatos(IEnumerable<DatoConsultado> datos)
    {
        foreach (var dato in datos)
        {
            AgregarSiFalta(_datos, dato);
        }
    }

    public void RegistrarResumen(ResumenEstudiante resumen) => _resumenes[resumen.EstudianteId] = resumen;

    public void RegistrarReglas(IEnumerable<int> entradas) => _entradasDeReglas.UnionWith(entradas);

    public void RegistrarCita(Cita cita) => AgregarSiFalta(_citas, cita);

    public void AgregarFuente(string texto) => _fuentes.Add(texto);

    private static void AgregarSiFalta<T>(List<T> lista, T valor)
    {
        if (!lista.Contains(valor))
        {
            lista.Add(valor);
        }
    }
}
using TutorFlow.Core.Academico;

namespace TutorFlow.Core.Asistente;

internal static class DatosLeidos
{
    public static DatoConsultado SinAsignatura(string estudianteId, string programaId, RecursoConsultado recurso) =>
        new(estudianteId, programaId, recurso);

    public static IEnumerable<DatoConsultado> PorAsignatura(
        ResumenEstudiante resumen,
        string programaId,
        params RecursoConsultado[] recursos) =>
        PorCodigos(resumen.EstudianteId, programaId, resumen.Asignaturas.Select(r => r.Asignatura.Codigo), recursos);

    public static IEnumerable<DatoConsultado> PorCodigos(
        string estudianteId,
        string programaId,
        IEnumerable<string> codigos,
        params RecursoConsultado[] recursos) =>
        recursos.SelectMany(recurso => codigos.Select(codigo => new DatoConsultado(estudianteId, programaId, recurso, codigo)));
}
using TutorFlow.Core.Academico;

namespace TutorFlow.Core.Asistente;

internal static class ResumenesAcademicos
{
    public static async Task<ResumenEstudiante> ResumirAsync(IApiAcademica api, string estudianteId, CancellationToken cancellationToken) =>
        await ResumirAsync(api, estudianteId, await api.ObtenerNotasAsync(estudianteId, cancellationToken), cancellationToken);

    public static async Task<ResumenEstudiante> ResumirAsync(
        IApiAcademica api,
        string estudianteId,
        IReadOnlyList<NotasAsignatura> notas,
        CancellationToken cancellationToken)
    {
        var asistencia = await api.ObtenerAsistenciaAsync(estudianteId, cancellationToken);
        var asignaturas = notas.Select(nota => new Asignatura(
            nota.Codigo,
            nota.Nombre,
            nota.Creditos,
            nota.Cortes,
            asistencia.FirstOrDefault(a => a.Codigo == nota.Codigo)?.Asistencia ?? new Asistencia(0, null))).ToList();
        return CalculosAcademicos.ResumirEstudiante(estudianteId, asignaturas);
    }
}

