        (CampoDePersona.Notas, ["notas", "corte", "cortes"]),
        (CampoDePersona.Estado, ["perdi", "perdida", "perdidas", "perdido", "aprobe", "aprobada", "gane", "reprobe", "pase", "habilitar", "habilitable", "estado", "voy"]),
        (CampoDePersona.Promedio, ["promedio", "ponderado"]),
        (CampoDePersona.PruebaAcademica, ["prueba academica"]),
        (CampoDePersona.Beca, ["beca", "becas"]),
        (CampoDePersona.Faltas, ["falta", "faltas", "inasistencia", "inasistencias", "asistencia"])
    ];

    public static IReadOnlyList<CampoDePersona> De(IReadOnlyList<string> palabras)
    {
        var texto = $" {string.Join(' ', palabras)} ";
        var pedidos = Tabla
            .Where(fila => fila.Terminos.Any(termino => texto.Contains($" {termino} ", StringComparison.Ordinal)))
            .Select(fila => fila.Campo)
            .ToList();
        return pedidos.Count == 0 ? [.. Enum.GetValues<CampoDePersona>()] : pedidos;
    }
}

using TutorFlow.Core.Academico;

namespace TutorFlow.Core.Asistente;

internal static class TextoDelDesglose
{
    private const string TotalSinRegistro = "Total: sin registro";

    public static IEnumerable<string> Lineas(IReadOnlyList<ResultadoAsignatura> elegidas, bool terceraPersona) =>
        elegidas.Count == 0
            ? []
            : elegidas.Select(resultado => FormateadorDatos.LineaDeAsistencia(resultado, terceraPersona)).Append(Total(elegidas));

    private static string Total(IReadOnlyList<ResultadoAsignatura> elegidas)
    {
        var conRegistro = elegidas.Where(resultado => resultado.Asignatura.Asistencia.Inasistencias is not null).ToList();
        var sinRegistro = elegidas.Except(conRegistro).Select(resultado => resultado.Asignatura.Nombre).ToList();
        var faltas = conRegistro.Sum(resultado => resultado.Asignatura.Asistencia.Inasistencias.GetValueOrDefault());
        return conRegistro.Count == 0 ? TotalSinRegistro : $"Total: {faltas} faltas{Complemento(sinRegistro)}";
    }

    private static string Complemento(List<string> sinRegistro) =>
        sinRegistro.Count == 0 ? string.Empty : $" (sin registro: {string.Join(", ", sinRegistro)})";
}

